class DB {
  constructor(){this.db=null}
  async open(){
    this.db=await new Promise((resolve,reject)=>{
      const r=indexedDB.open(DB_NAME,DB_VERSION);
      r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains('app'))d.createObjectStore('app');if(!d.objectStoreNames.contains('snapshots'))d.createObjectStore('snapshots',{keyPath:'id'})};
      r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);
    });return this;
  }
  get(store,key){return new Promise((res,rej)=>{const tx=this.db.transaction(store,'readonly'),r=tx.objectStore(store).get(key);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
  put(store,val,key){return new Promise((res,rej)=>{const tx=this.db.transaction(store,'readwrite'),os=tx.objectStore(store),r=key===undefined?os.put(val):os.put(val,key);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
  del(store,key){return new Promise((res,rej)=>{const tx=this.db.transaction(store,'readwrite'),r=tx.objectStore(store).delete(key);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
  all(store){return new Promise((res,rej)=>{const tx=this.db.transaction(store,'readonly'),r=tx.objectStore(store).getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}
}
