class AudioEngine{
  constructor(){this.ctx=null;this.master=null;this.ambientGain=null;this.sfxGain=null;this.uiGain=null;this.ambient=null}
  unlock(){if(this.ctx)return;try{this.ctx=new (window.AudioContext||window.webkitAudioContext)();this.master=this.ctx.createGain();this.ambientGain=this.ctx.createGain();this.sfxGain=this.ctx.createGain();this.uiGain=this.ctx.createGain();this.ambientGain.connect(this.master);this.sfxGain.connect(this.master);this.uiGain.connect(this.master);this.master.connect(this.ctx.destination);this.apply();}catch{} }
  apply(){if(!this.ctx||!model)return;const s=model.settings.audio;this.master.gain.value=s.mute?0:s.master;this.ambientGain.gain.value=s.ambient;this.sfxGain.gain.value=s.sfx;this.uiGain.gain.value=s.ui}
  tone(freq=440,dur=.12,type='sine',gain=.05,branch='ui'){if(!this.ctx||model.settings.audio.mute)return;const o=this.ctx.createOscillator(),g=this.ctx.createGain(),dest=branch==='sfx'?this.sfxGain:this.uiGain;o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(gain,this.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.0001,this.ctx.currentTime+dur);o.connect(g);g.connect(dest);o.start();o.stop(this.ctx.currentTime+dur)}
  sfx(kind){if(kind==='success'){this.tone(523,.12,'triangle',.06,'sfx');setTimeout(()=>this.tone(784,.22,'triangle',.05,'sfx'),90)}else if(kind==='danger'){this.tone(120,.34,'sawtooth',.05,'sfx')}else if(kind==='portal'){this.tone(260,.2,'sine',.04,'sfx');setTimeout(()=>this.tone(390,.28,'sine',.04,'sfx'),80)}else this.tone(310,.08,'triangle',.035,'ui')}
  setAmbient(on){if(!this.ctx)return;if(!on){if(this.ambient){this.ambient.stop();this.ambient=null}return}if(this.ambient)return;const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type='sine';o.frequency.value=64;g.gain.value=.018;o.connect(g);g.connect(this.ambientGain);o.start();this.ambient=o}
}
