function assignMissingRegions(lessonId){const regs=ensureRegionsForLesson(lessonId);let i=0;for(const n of topNodes(lessonId)){if(!n.regionId||!regs.some(r=>r.id===n.regionId)){n.regionId=regs[i%regs.length].id;i++}}}
function recalcProgression(){
  const verified=model.nodes.filter(n=>n.status==='cleared').length;
  const delayed=model.attempts.filter(a=>a.result==='passed'&&a.isReview).length;
  const gaps=model.gaps.filter(g=>g.state==='resolved').length;
  const bosses=model.bosses.filter(b=>b.state==='defeated').length;
  const xp=verified*35+delayed*20+gaps*80+bosses*180;
  model.profile.xp=xp;model.profile.level=1+Math.floor(Math.sqrt(xp/120));
  const masteryScore=verified+delayed*.6+gaps*1.8+bosses*4;model.profile.knowledgeRank=masteryScore>=220?'S':masteryScore>=120?'A':masteryScore>=70?'B':masteryScore>=35?'C':masteryScore>=15?'D':'E';
  const defs=[['first_monster','Первая победа','Победить первого монстра',()=>gaps>=1],['deep_dungeon','Глубокое подземелье','Достичь глубины 3',()=>deepestDungeon()>=3],['verified_100','100 подтверждённых тем','Подтвердить 100 тем',()=>verified>=100],['five_delayed','Память крепнет','5 успешных отложенных retrieval',()=>delayed>=5],['boss_first','Падение босса','Победить первого босса',()=>bosses>=1]];
  for(const [id,title,desc,test] of defs)if(test()&&!model.achievements.some(a=>a.id===id)){model.achievements.push({id,title,description:desc,unlockedAt:now()});event('achievement',`Достижение: ${title}`,desc)}
}
function migrateModel(m){
  if(!m||typeof m!=='object')return defaultModel();
  const d=defaultModel();
  const out={...d,...m,settings:{...d.settings,...m.settings,graphics:{...d.settings.graphics,...m.settings?.graphics},audio:{...d.settings.audio,...m.settings?.audio},data:{...d.settings.data,...m.settings?.data}},ui:{...d.ui,...m.ui,filters:{...d.ui.filters,...m.ui?.filters},scene:{...d.ui.scene,...m.ui?.scene},cameraByScene:m.ui?.cameraByScene||{}}};
  for(const k of ['courses','lessons','regions','nodes','gaps','encounters','dungeons','bosses','attempts','reviews','events','achievements'])if(!Array.isArray(out[k]))out[k]=[];
  if(!out.bestiary||typeof out.bestiary!=='object')out.bestiary={records:{}};if(!out.bestiary.records)out.bestiary.records={};
  out.schemaVersion=SCHEMA_VERSION;out.appVersion=APP_VERSION;
  out.nodes.forEach(n=>{n.status=normalizeStatus(n.status);n.required=n.required!==false;n.notes=safeText(n.notes||'');n.criterion=safeText(n.criterion||'');if(!n.createdAt)n.createdAt=now();if(!n.updatedAt)n.updatedAt=n.createdAt});
  return out;
}
