  draw(){if(!this.camera||!this.canvas.width)return;const ctx=this.ctx,d=this.dpr,r=this.shell.getBoundingClientRect();ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,r.width,r.height);this.hits=[];this.drawBackground(ctx,r.width,r.height);ctx.save();ctx.translate(r.width/2,r.height/2);ctx.scale(this.camera.zoom,this.camera.zoom);ctx.translate(-this.camera.x,-this.camera.y);this.drawRegions(ctx);this.drawRoads(ctx);this.drawNodes(ctx);this.drawBosses(ctx);ctx.restore();this.drawVignette(ctx,r.width,r.height);this.drawMinimap()}
