function isReviewDue(n){return !!n.reviewDueAt&&n.reviewDueAt<=now()}
function reviewQueue(){const due=model.nodes.filter(n=>!n.archived&&(n.status==='unstable'||isReviewDue(n)));return due.sort((a,b)=>(a.reviewDueAt||0)-(b.reviewDueAt||0))}
function reviewSchedule(node,result){const day=86400000;const successes=node.successfulRetrievals||0;let days=1;if(result==='passed')days=[1,3,7,18,45,90][Math.min(successes,5)];else if(result==='partial')days=1;else days=0;node.reviewDueAt=now()+Math.max(.25,days)*day}

