async function enterDungeon(did){const d=model.dungeons.find(x=>x.id===did);if(!d)return;model.ui.scene={type:'dungeon',dungeonId:did};model.ui.view='world';event('dungeon_entered',`Вход в Hidden Dungeon`,`Глубина ${d.depth}`,did);await persist();closeModal();closeInspector();render();cinematic(`DUNGEON DEPTH ${d.depth}`,dungeonName(d,SPECIES_MAP.get(encounterForDungeon(did)?.speciesId)),'danger',850);audio.sfx('portal');if(d.depth>=7)toast(`Глубина Dungeon: ${d.depth}. Возможно, часть узлов стоит объединить.`)}
async function exitDungeon(){const d=model.dungeons.find(x=>x.id===model.ui.scene.dungeonId);if(d?.parentDungeonId)model.ui.scene={type:'dungeon',dungeonId:d.parentDungeonId};else model.ui.scene={type:'world',dungeonId:null};await persist();closeInspector();render();audio.sfx('portal')}
function readinessForEncounter(enc){const nodes=dungeonNodes(enc.dungeonId),required=nodes.filter(n=>n.required!==false),ready=required.length>0&&required.every(n=>n.status==='cleared'),p=progressForNodes(required);return{ready,nodes:required,p,message:!required.length?'Добавьте хотя бы одну обязательную подтему':ready?'Все обязательные слабые места закрыты':`Закрыто ${p.cleared}/${p.total} обязательных подтем`}}
function finalStrike(encId){const enc=model.encounters.find(e=>e.id===encId);if(!enc||enc.state==='defeated')return;const r=readinessForEncounter(enc);if(!r.ready)return toast(r.message,'bad');const parent=model.nodes.find(n=>n.id===enc.parentNodeId);if(!parent)return;closeInspector();openTrial(parent.id,{finalStrikeEncounterId:encId});cinematic('FINAL STRIKE','PROVE MASTERY','boss',800)}
async function defeatEncounter(encId,fromTrial=false){const enc=model.encounters.find(e=>e.id===encId);if(!enc)return false;const r=readinessForEncounter(enc);if(!r.ready){toast(r.message,'bad');return false}enc.state='defeated';enc.defeatedAt=now();const gap=model.gaps.find(g=>g.id===enc.gapId);if(gap){gap.state='resolved';gap.resolvedAt=now()}const d=model.dungeons.find(d=>d.id===enc.dungeonId);if(d)d.status='cleared';const rec=model.bestiary.records[enc.speciesId];if(rec)rec.timesDefeated=(rec.timesDefeated||0)+1;const parent=model.nodes.find(n=>n.id===enc.parentNodeId);if(parent){parent.status='cleared';parent.lastVerifiedAt=now();if(!fromTrial)parent.successfulRetrievals=(parent.successfulRetrievals||0)+1;reviewSchedule(parent,'passed')}const sp=SPECIES_MAP.get(enc.speciesId);event('monster_defeated',`MONSTER DEFEATED: ${gap?.title||sp?.name}`,sp?.name||'',enc.id);recalcProgression();await persist();cinematic('KNOWLEDGE GAP RESOLVED',sp?.name||'MONSTER DEFEATED','success',1400);audio.sfx('success');return true}

async function sha256(textValue){const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(textValue));return [...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,'0')).join('')}
async function exportBackup(){
  const data=structuredClone(model);const events=data.events;const settings=data.settings;delete data.events;delete data.settings;
  const dataJson=JSON.stringify(data),eventsJson=JSON.stringify(events),settingsJson=JSON.stringify(settings);const checksums={data:await sha256(dataJson),events:await sha256(eventsJson),settings:await sha256(settingsJson)};
  const envelope={manifest:{format:'SoloStudyMapBackup',formatVersion:1,schemaVersion:SCHEMA_VERSION,createdAt:new Date().toISOString(),appVersion:APP_VERSION,recordCounts:{courses:model.courses.length,lessons:model.lessons.length,nodes:model.nodes.length,gaps:model.gaps.length,encounters:model.encounters.length,dungeons:model.dungeons.length,events:model.events.length}},data,events,settings,checksums};
  const blob=new Blob([JSON.stringify(envelope)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`solo-study-map-${new Date().toISOString().slice(0,10)}.ssmbackup`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);event('backup_created','Создана резервная копия',a.download);await persist();toast('Резервная копия создана','good')
}
function openImportPicker(){const f=document.createElement('input');f.type='file';f.accept='.ssmbackup,.json,application/json';f.addEventListener('change',()=>{const file=f.files?.[0];if(file)previewImport(file)});f.click()}
async function previewImport(file){if(file.size>50*1024*1024)return toast('Backup больше 50 МБ — импорт остановлен','bad');let obj;try{obj=JSON.parse(await file.text())}catch{return toast('Файл не является корректным backup','bad')}try{const clean=await validateBackup(obj);const wrap=modalTitle('Предпросмотр восстановления','Данные сначала проверены. Перед заменой текущей базы будет создан автоматический snapshot.');const info=text('div',null,'card card-pad');const m=clean.manifest;info.append(text('div',`Курсы: ${m.recordCounts?.courses??clean.data.courses.length}`),text('div',`Уроки: ${m.recordCounts?.lessons??clean.data.lessons.length}`),text('div',`Темы: ${m.recordCounts?.nodes??clean.data.nodes.length}`),text('div',`Версия схемы: ${m.schemaVersion}`),text('div',`Создано: ${m.createdAt}`));wrap.appendChild(info);const acts=text('div',null,'modal-actions');acts.append(button('Отмена','close-modal','btn ghost'));const b=button('Восстановить','confirm-import','btn danger');b._backup=clean;acts.appendChild(b);wrap.appendChild(acts);openModal(wrap)}catch(e){toast(`Backup отклонён: ${e.message}`,'bad')}}
async function validateBackup(obj){if(!obj||obj.manifest?.format!=='SoloStudyMapBackup')throw new Error('неверный формат');if(obj.manifest.formatVersion!==1)throw new Error('неподдерживаемая версия формата');if(!obj.data||!Array.isArray(obj.data.courses)||!Array.isArray(obj.data.lessons)||!Array.isArray(obj.data.nodes))throw new Error('повреждена структура данных');const dj=JSON.stringify(obj.data),ej=JSON.stringify(obj.events||[]),sj=JSON.stringify(obj.settings||{});if(obj.checksums){if(obj.checksums.data!==await sha256(dj)||obj.checksums.events!==await sha256(ej)||obj.checksums.settings!==await sha256(sj))throw new Error('контрольная сумма не совпала')}const clean=sanitizeObject(structuredClone(obj));const ids=new Set(clean.data.nodes.map(n=>n.id));if(ids.size!==clean.data.nodes.length)throw new Error('дублирующиеся ID тем');return clean}
function sanitizeObject(v,depth=0){if(depth>40)throw new Error('слишком глубокая структура');if(typeof v==='string')return safeText(v,20000);if(Array.isArray(v))return v.slice(0,100000).map(x=>sanitizeObject(x,depth+1));if(v&&typeof v==='object'){const o={};for(const [k,val] of Object.entries(v)){if(/^on/i.test(k)||['__proto__','constructor','prototype'].includes(k))continue;o[safeText(k,100)]=sanitizeObject(val,depth+1)}return o}return v}
async function confirmImport(btn){const b=btn._backup;if(!b)return;await snapshot('Перед восстановлением backup');const restored={...b.data,events:b.events||[],settings:b.settings||defaultModel().settings};model=migrateModel(restored);event('backup_restored','Backup восстановлен',`Исходная версия: ${b.manifest.appVersion||'неизвестна'}`);await persist();closeModal();render();toast('Данные восстановлены','good')}
async function openSnapshots(){const all=(await db.all('snapshots')).sort((a,b)=>b.createdAt-a.createdAt),wrap=modalTitle('Автоматические snapshots','Хранятся последние 5 контрольных точек перед рискованными операциями.');const list=text('div',null,'review-list');for(const s of all){const row=text('div',null,'card review-row'),body=text('div');body.append(text('h4',s.reason),text('p',fmtTime(s.createdAt)));const b=button('Восстановить','restore-one-snapshot','btn small danger');b._snapshot=s;row.append(body,b);list.appendChild(row)}if(!all.length)list.appendChild(text('div','Snapshots ещё не создавались.','empty-state'));wrap.appendChild(list);wrap.appendChild(text('div',null,'modal-actions')).appendChild(button('Закрыть','close-modal','btn ghost'));openModal(wrap,{wide:true})}
async function restoreSnapshot(btn){const s=btn._snapshot;if(!s||!confirm(`Восстановить snapshot «${s.reason}»? Текущее состояние будет сохранено новым snapshot.`))return;await snapshot('Перед ручным восстановлением snapshot');model=migrateModel(structuredClone(s.state));event('snapshot_restored','Snapshot восстановлен',s.reason);await persist();closeModal();render();toast('Snapshot восстановлен','good')}

function openFilters(){if(!world)return;const existing=$('.filter-pop');if(existing){existing.remove();return}const pop=text('div',null,'filter-pop');for(const [key,label] of [['cleared','CLEARED'],['unstable','UNSTABLE'],['locked','LOCKED'],['monsters','Монстры'],['due','Due review']]){const lab=text('label'),c=document.createElement('input');c.type='checkbox';c.checked=model.ui.filters[key];c.dataset.filter=key;lab.append(c,text('span',label));pop.appendChild(lab)}world.shell.appendChild(pop);pop.addEventListener('change',e=>{if(e.target.dataset.filter){model.ui.filters[e.target.dataset.filter]=e.target.checked;schedulePersist();world.draw()}})}
function openBeastDetail(id){const s=SPECIES_MAP.get(id),rec=model.bestiary.records[id];if(!s)return;const wrap=modalTitle(rec?s.name:'Неизвестный вид',s.familyName),art=text('div',null,'entity-art'),cv=document.createElement('canvas');cv.width=900;cv.height=430;art.appendChild(cv);wrap.appendChild(art);requestAnimationFrame(()=>drawMonster(cv,s,rec?.lastVariantSeed||s.seed,rec?1:.35));const info=text('div',null,'card card-pad');info.append(text('div',`Семейство: ${s.familyName}`),text('div',`Предпочитаемый биом: ${BIOMES[s.preferredBiome]?.name}`),text('div',rec?`Встречено: ${rec.timesEncountered||0} · Побед: ${rec.timesDefeated||0} · Высший Tier: ${rec.highestTier||'E'}`:'Этот вид ещё не встречался.'));wrap.appendChild(info);wrap.appendChild(text('div',null,'modal-actions')).appendChild(button('Закрыть','close-modal','btn ghost'));openModal(wrap,{wide:true})}

async function requestPersistence(){if(!navigator.storage?.persist)return toast('Эта версия браузера не поддерживает запрос persistent storage','bad');try{const ok=await navigator.storage.persist();model.settings.data.persistentRequested=true;await persist();toast(ok?'Браузер подтвердил постоянное хранилище':'Браузер не гарантировал постоянное хранилище — регулярно делай backup',ok?'good':'');checkStorageStatus()}catch{toast('Не удалось запросить persistent storage','bad')}}

function setView(view){model.ui.view=view;if(view!=='world')model.ui.editMode=false;closeModal();closeInspector();render()}
function openLesson(id){const l=model.lessons.find(x=>x.id===id);if(!l)return;model.ui.activeLessonId=l.id;model.ui.activeCourseId=l.courseId;model.ui.scene={type:'world',dungeonId:null};model.ui.view='world';assignMissingRegions(l.id);render()}
function jumpNode(id){const n=model.nodes.find(x=>x.id===id);if(!n)return;const l=model.lessons.find(x=>x.id===n.lessonId);model.ui.activeLessonId=n.lessonId;model.ui.activeCourseId=l?.courseId||model.ui.activeCourseId;model.ui.scene=n.dungeonId?{type:'dungeon',dungeonId:n.dungeonId}:{type:'world',dungeonId:null};model.ui.view='world';closeModal();render();setTimeout(()=>{if(world&&n.position){world.camera.x=n.position.x;world.camera.y=n.position.y;world.camera.zoom=1.2;world.saveCamera();world.draw();openNodeInspector(n.id)}},120)}
function searchJump(type,id){if(type==='course'){model.ui.activeCourseId=id;model.ui.activeLessonId=model.lessons.find(l=>l.courseId===id)?.id||null;setView('library')}else if(type==='lesson')openLesson(id);else if(type==='node')jumpNode(id);else if(type==='gap'){const g=model.gaps.find(x=>x.id===id),e=g&&model.encounters.find(x=>x.gapId===g.id);if(e){jumpNode(e.parentNodeId);setTimeout(()=>openMonsterInspector(e.id),160)}}}

async function registerSW(){if(!('serviceWorker'in navigator))return;try{const reg=await navigator.serviceWorker.register('./sw.js');if(reg.waiting)updateWaiting=reg.waiting;reg.addEventListener('updatefound',()=>{const nw=reg.installing;if(!nw)return;nw.addEventListener('statechange',()=>{if(nw.state==='installed'&&navigator.serviceWorker.controller){updateWaiting=nw;toast('Готово обновление приложения. Установите его в настройках.')}})});navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload())}catch(e){console.warn('SW registration failed',e)}}
async function checkUpdate(){if(updateWaiting){await snapshot('Перед обновлением приложения');await persist();updateWaiting.postMessage({type:'SKIP_WAITING'});return}try{const reg=await navigator.serviceWorker.getRegistration();await reg?.update();toast('Проверка обновлений завершена')}catch{toast('Не удалось проверить обновление','bad')}}
let installPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;toast('Solo Study Map можно установить как приложение')});

function modalConfirm(titleTxt,message,yesAction,id){const wrap=modalTitle(titleTxt,message),box=text('div','Это действие можно частично восстановить из автоматического snapshot.','danger-box');wrap.appendChild(box);const acts=text('div',null,'modal-actions');acts.append(button('Отмена','close-modal','btn ghost'));const b=button('Удалить',yesAction,'btn danger');b.dataset.id=id;acts.appendChild(b);wrap.appendChild(acts);openModal(wrap)}

document.addEventListener('click',async e=>{
  audio.unlock();const nav=e.target.closest('[data-view]');if(nav){setView(nav.dataset.view);return}
  const crumb=e.target.closest('[data-crumb]');if(crumb){const c=crumb.dataset.crumb;if(c==='course')setView('library');else if(c==='lesson'){model.ui.scene={type:'world',dungeonId:null};setView('world')}else if(c.startsWith('dungeon:'))enterDungeon(c.slice(8));return}
  const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
  try{
    if(a==='go-home')setView('home');
    else if(a==='go-world'){model.ui.view='world';model.ui.scene={type:'world',dungeonId:null};render()}
    else if(a==='go-library')setView('library');
    else if(a==='settings')setView('settings');
    else if(a==='search')openSearch();
    else if(a==='review')openReviewModal();
    else if(a==='new-course')openCourseModal();
    else if(a==='edit-course')openCourseModal(b.dataset.id);
    else if(a==='save-course')await saveCourse(b.dataset.id||null);
    else if(a==='confirm-delete-course')modalConfirm('Удалить курс?','Будут удалены все уроки и учебные данные этого курса.','delete-course-now',b.dataset.id);
    else if(a==='delete-course-now')await deleteCourse(b.dataset.id);
    else if(a==='select-course'){model.ui.activeCourseId=b.dataset.id;const l=model.lessons.find(x=>x.courseId===b.dataset.id);if(l)model.ui.activeLessonId=l.id;render()}
    else if(a==='new-lesson')openLessonModal();
    else if(a==='edit-lesson')openLessonModal(b.dataset.id);
    else if(a==='save-lesson')await saveLesson(b.dataset.id||null);
    else if(a==='confirm-delete-lesson')modalConfirm('Удалить урок?','Темы, монстры, подземелья и история этого урока будут удалены.','delete-lesson-now',b.dataset.id);
    else if(a==='delete-lesson-now')await deleteLesson(b.dataset.id);
    else if(a==='open-lesson')openLesson(b.dataset.id);
    else if(a==='bulk-topics')openBulkModal(b.dataset.id);
    else if(a==='bulk-preview')await bulkPreview(b.dataset.id);
    else if(a==='bulk-confirm')await bulkConfirm(b);
    else if(a==='add-topic')openNodeModal(null,null);
    else if(a==='add-subtopic')openNodeModal(null,model.ui.scene.dungeonId);
    else if(a==='edit-node')openNodeModal(b.dataset.id,null);
    else if(a==='save-node')await saveNode(b.dataset.id||null,b.dataset.dungeon||null);
    else if(a==='delete-node')await deleteNode(b.dataset.id);
    else if(a==='detect-gap')openGapModal(b.dataset.id);
    else if(a==='spawn-monster')await spawnMonster(b.dataset.id);
    else if(a==='trial-node')openTrial(b.dataset.id);
    else if(a==='review-node'){closeModal();openTrial(b.dataset.id,{isReview:true})}
    else if(a==='trial-confidence'){$$('.confidence button').forEach(x=>x.classList.remove('active'));b.classList.add('active')}
    else if(a==='trial-reveal')revealTrial(b);
    else if(a==='trial-result')await applyTrialResult(b);
    else if(a==='close-modal')closeModal();
    else if(a==='close-inspector')closeInspector();
    else if(a==='center-world')world?.center();
    else if(a==='toggle-filters')openFilters();
    else if(a==='toggle-edit'){model.ui.editMode=!model.ui.editMode;render();toast(model.ui.editMode?'Режим редактора включён':'Режим редактора выключен')}
    else if(a==='rebuild-layout'){if(world){pushUndo();await world.layout(true);world.center();toast('Мир перестроен','good')}}
    else if(a==='undo')await undo();
    else if(a==='redo')await redo();
    else if(a==='topic-list')openTopicList();
    else if(a==='add-region')openRegionModal();
    else if(a==='save-region')await addRegion();
    else if(a==='enter-dungeon')await enterDungeon(b.dataset.id);
    else if(a==='exit-dungeon')await exitDungeon();
    else if(a==='final-strike'){const enc=encounterForDungeon(model.ui.scene.dungeonId);if(enc)finalStrike(enc.id)}
    else if(a==='final-strike-monster')finalStrike(b.dataset.id);
    else if(a==='jump-node')jumpNode(b.dataset.id);
    else if(a==='search-jump')searchJump(b.dataset.type,b.dataset.id);
    else if(a==='bosses')openBosses();
    else if(a==='open-boss'){const id=b.dataset.id;closeModal();openBossInspector(id)}
    else if(a==='challenge-boss')challengeBoss(b.dataset.id);
    else if(a==='beast-detail')openBeastDetail(b.dataset.id);
    else if(a==='beast-jump'){closeInspector();model.ui.bestiaryFamily='all';model.ui.bestiaryStatus='all';model.ui.bestiaryPage=Math.floor(SPECIES.findIndex(s=>s.id===b.dataset.id)/64);setView('bestiary')}
    else if(a==='bestiary-prev'){model.ui.bestiaryPage=Math.max(0,(model.ui.bestiaryPage||0)-1);render()}
    else if(a==='bestiary-next'){model.ui.bestiaryPage=(model.ui.bestiaryPage||0)+1;render()}
    else if(a==='export-backup')await exportBackup();
    else if(a==='import-backup')openImportPicker();
    else if(a==='confirm-import')await confirmImport(b);
    else if(a==='restore-snapshot')await openSnapshots();
    else if(a==='restore-one-snapshot')await restoreSnapshot(b);
    else if(a==='request-persistence')await requestPersistence();
    else if(a==='check-update')await checkUpdate();
  }catch(err){console.error(err);toast(`Ошибка: ${err.message||err}`,'bad')}
});

document.addEventListener('change',e=>{
  const t=e.target;
  if(t.dataset.action==='bestiary-family'){model.ui.bestiaryFamily=t.value;model.ui.bestiaryPage=0;render()}
  else if(t.dataset.action==='bestiary-status'){model.ui.bestiaryStatus=t.value;model.ui.bestiaryPage=0;render()}
  else if(t.dataset.action==='chronicle-filter'){model.ui.chronicleFilter=t.value;render()}
  else if(t.dataset.action==='setting-switch'){const g=t.dataset.group,k=t.dataset.key;model.settings[g][k]=!model.settings[g][k];audio.apply();render()}
  else if(t.dataset.action==='setting-range'){const g=t.dataset.group,k=t.dataset.key;model.settings[g][k]=Number(t.value);audio.apply();schedulePersist()}
  else if(t.dataset.action==='setting-select'){const g=t.dataset.group,k=t.dataset.key;model.settings[g][k]=t.value;schedulePersist();render()}
});

window.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeInspector()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}});
window.addEventListener('pointerdown',()=>{audio.unlock();if(model?.settings?.audio?.ambient>0&&!model.settings.audio.mute)audio.setAmbient(true)},{once:true});

(async function bootstrap(){
  try{await loadModel();for(const l of model.lessons){ensureRegionsForLesson(l.id);assignMissingRegions(l.id)}recalcProgression();await persist();$('#boot').hidden=true;$('#app').hidden=false;render();await registerSW();if(navigator.storage?.persisted){const p=await navigator.storage.persisted();if(!p&&model.nodes.length>3&&!model.settings.data.persistentRequested)setTimeout(()=>toast('Совет: в настройках можно запросить постоянное хранилище и сделать backup.'),1600)}}catch(err){console.error(err);$('#boot').querySelector('p').textContent='Не удалось открыть локальную базу. Перезагрузите страницу.';$('#boot').querySelector('p').style.color='#ff8da0'}})();
